// Evalúa evaluar = (3 + 4) * 2 ^ 3 - 10 / 4.
FUNCIÓN evaluar() → real
    // Evaluar la expresión completa
    resultado ← (3.0 + 4.0) × 2.0 ^ 3.0 − 10.0 ÷ 4.0
    DEVOLVER resultado
FIN FUNCIÓN

// Calcula el área del círculo.
FUNCIÓN areaCirculo(radio: real) → real
    // Una longitud no puede ser cero ni negativa
    SI radio ≤ 0.0 ENTONCES
        ERROR "Las medidas deben ser positivas"
    FIN SI
    // A = π · radio · radio
    DEVOLVER π × radio × radio
FIN FUNCIÓN

// Calcula el área del triángulo.
FUNCIÓN areaTriangulo(base: real, altura: real) → real
    // Una longitud no puede ser cero ni negativa
    SI base ≤ 0.0 O altura ≤ 0.0 ENTONCES
        ERROR "Las medidas deben ser positivas"
    FIN SI
    // A = base · altura / 2
    DEVOLVER base × altura ÷ 2.0
FIN FUNCIÓN

// Calcula el área del triángulo.
FUNCIÓN areaTriangulo(a: real, b: real, c: real) → real
    // Una longitud no puede ser cero ni negativa
    SI a ≤ 0.0 O b ≤ 0.0 O c ≤ 0.0 ENTONCES
        ERROR "Las medidas deben ser positivas"
    FIN SI
    // Cada lado debe ser menor que la suma de los otros dos
    SI a + b ≤ c O a + c ≤ b O b + c ≤ a ENTONCES
        ERROR "Los lados no cumplen la desigualdad triangular"
    FIN SI
    // Semiperímetro
    s ← (a + b + c) ÷ 2.0
    // Fórmula de Herón
    DEVOLVER RAÍZ(s × (s − a) × (s − b) × (s − c))
FIN FUNCIÓN

// Calcula el perímetro del rectángulo.
FUNCIÓN perimetroRectangulo(base: real, altura: real) → real
    // Una longitud no puede ser cero ni negativa
    SI base ≤ 0.0 O altura ≤ 0.0 ENTONCES
        ERROR "Las medidas deben ser positivas"
    FIN SI
    // P = 2 · (base + altura)
    DEVOLVER 2.0 × (base + altura)
FIN FUNCIÓN

// Busca un valor en una lista (búsqueda lineal).
FUNCIÓN buscar(valores: lista de enteros, objetivo: entero) → entero
    // Índices de 0 a n − 1
    PARA i DESDE 0 HASTA LONGITUD(valores) − 1 HACER
        SI valores[i] = objetivo ENTONCES
            // Primera aparición
            DEVOLVER i
        FIN SI
    FIN PARA
    // -1 indica "no está"
    DEVOLVER −1
FIN FUNCIÓN

