// Calcula el n-ésimo término de una sucesión aritmética.
FUNCIÓN terminoAritmetico(primero: real, diferencia: real, n: entero) → real
    // Las posiciones empiezan en 1
    SI n < 1 ENTONCES
        ERROR "n debe ser al menos 1"
    FIN SI
    // a(n) = a1 + (n − 1) · d
    DEVOLVER primero + REAL(n − 1) × diferencia
FIN FUNCIÓN

